enum State { GREEN, YELLOW, RED };
State state = GREEN;
unsigned long t0 = 0;
const unsigned long DUR[] = {4000, 1000, 3000};   // ms per state
const int PIN[] = {11, 12, 13};

void setup() {
  for (int i = 0; i < 3; i++) pinMode(PIN[i], OUTPUT);
  Serial.begin(115200);
}

void loop() {
  if (millis() - t0 >= DUR[state]) {          // overflow-safe comparison
    t0 = millis();
    state = (State)((state + 1) % 3);
    Serial.print("state -> "); Serial.println(state);
  }
  for (int i = 0; i < 3; i++) digitalWrite(PIN[i], i == state);
  // other tasks can run here without waiting
}

