volatile long ticks = 0;

void onTick() {            // ISR: keep it tiny
  ticks++;
}

void setup() {
  Serial.begin(115200);
  pinMode(2, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(2), onTick, RISING);
}

void loop() {
  static unsigned long t0 = 0;
  if (millis() - t0 >= 100) {          // report at 10 Hz
    t0 = millis();
    noInterrupts();
    long copy = ticks;                 // a long is 4 bytes: copy atomically
    interrupts();
    Serial.println(copy);
  }
}

// line_fsm.h: pure logic, no Arduino headers, so it compiles on the PC too
enum class Mode { Straight, Left, Right, Lost };

inline Mode decide(bool leftOnLine, bool rightOnLine, Mode last) {
  if (leftOnLine && rightOnLine) return Mode::Straight;
  if (leftOnLine) return Mode::Left;
  if (rightOnLine) return Mode::Right;
  return last == Mode::Left || last == Mode::Right ? last : Mode::Lost;
}

// test_line_fsm.cpp (host): g++ -std=c++17 test_line_fsm.cpp && ./a.out
#include <cassert>
int main() {
  assert(decide(true, true, Mode::Lost) == Mode::Straight);
  assert(decide(false, false, Mode::Left) == Mode::Left);   // keep turning
  assert(decide(false, false, Mode::Straight) == Mode::Lost);
}

